class Solution {
    public int majorityElement(int[] nums) {
        int count=0;
        int element = -1;
        for(int i=0;i<nums.length;i++){
            if(count==0){
                element = nums[i];
                count++;
            }else{
                if(element==nums[i]){
                    count++;
                }else{
                    count--;
                }
            }
        }
        count=0;
        for(int i=0;i<nums.length;i++){
            if(nums[i]==element){
                count++;
            }
        }
        return count>(nums.length/2)?element:-1;
    }
}

