            return true;
        int no = nums[0];
        boolean isRotated = false;

        for (int i = 0; i < nums.length; i++) {
            if (!isRotated && no > nums[i]) {
                isRotated = true;
                no = nums[i];
            } else if (isRotated && no > nums[i]) {
                isRotated = false;
                no = nums[i];
                return false;
            } else if (no <= nums[i]) {
                no = nums[i];
            }
        }

        if (!isRotated) {//arr is already sorted 
            return true;
        } else if (isRotated) {
            return no <= nums[0];
        }

        return isRotated;
    }
}

